 "content": "def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==2]
    if not pts: return out
    r0,c0=pts[0]
    # Each 8-pattern is a set of interrupted tracks. Complete a gap if
    # the color-8 track has an interruption; the seed's row/column is a ray.
    # Determine dominant orientation from the pattern of color-8 cells.
    row_counts=[sum(x==8 for x in row) for row in grid]
    col_counts=[sum(grid[r][c]==8 for r in range(h)) for c in range(w)]
    if max(row_counts,default=0)>max(col_counts,default=0):
        # Horizontal bands: extend seed column vertically.
        for r in range(r0,h): out[r][c0]=2
        tracks=[r for r,n in enumerate(row_counts) if n]
        for a,b in zip(tracks,tracks[1:]):
            for c in range(w):
                if grid[a][c]==0 and grid[b][c]==0:
                    for r in range(a+1,b): out[r][c]=2
    else:
        # Vertical tracks: extend from seed horizontally/vertically toward gaps.
        for c in range(c0): out[r0][c]=2
        for r in range(h):
            ps=[c for c in range(w) if grid[r][c]==8]
            # isolated missing runs across repeated vertical tracks are bridged
            if len(ps)>=2:
                for a,b in zip(ps,ps[1:]):
                    if b>a+1:
                        for c in range(a+1,b): out[r][c]=2
    return out
