    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    seeds=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==2]
    if not seeds: return out
    sr,sc=seeds[0]
    # Cross-grid pattern: color 2 fills blank cells at intersections of the
    # horizontal and vertical line-gap tracks. The seed selects the active
    # row/column; extend the corresponding grid line to the pattern.
    pattern_rows=[r for r in range(h) if 8 in grid[r]]
    pattern_cols=[c for c in range(w) if any(grid[r][c]==8 for r in range(h))]
    # Complete missing cells on all pattern rows/columns only where a 2-ray
    # from the seed reaches that track.
    for r in range(sr,h):
        if r in pattern_rows:
            for c in range(w):
                if grid[r][c]==0 and (c==sc or any(grid[r][x]==8 for x in range(w) if x==sc)):
                    out[r][c]=2
    for c in range(w):
        if c==sc: continue
        if c in pattern_cols:
            for r in range(h):
                if r==sr and grid[r][c]==0: out[r][c]=2
    # Fill aligned gaps between 8 marks in pattern rows/columns, retaining 8s.
    for r in pattern_rows:
        xs=[c for c in range(w) if grid[r][c]==8]
        for a,b in zip(xs,xs[1:]):
            if b>a+1:
                for c in range(a+1,b): out[r][c]=2
    for c in pattern_cols:
        xs=[r for r in range(h) if grid[r][c]==8]
        for a,b in zip(xs,xs[1:]):
            if b>a+1:
                for r in range(a+1,b): out[r][c]=2
    # Seed's own horizontal ray toward left edge.
    for c in range(sc):
        if grid[sr][c]==0: out[sr][c]=2
    return out
