    # horizontal/vertical gaps by marking only zeros between nearest 8 marks.
    for r in range(h):
        xs=[c for c in range(w) if grid[r][c]==8]
        for a,b in zip(xs,xs[1:]):
            if b>a+1:
                for c in range(a+1,b): out[r][c]=2
